// Generated by scripts/default-links.mjs from links.toml. Do not edit.
export const DEFAULT_LINKS_TOML: string = "# GraphOS Inspector link mappings: where a result row, or a search, opens.\n#\n# This is the shipped default. To add or change mappings, do not edit this\n# file (an update replaces it): create ~/.claude/graphos-agent-mods/links.toml with\n# only your additions, then run /gas links. Your rules come before these; your\n# [bases] entries replace these.\n\n# Named hosts. Every url below must start with one of these names in braces.\n# A host comes from here, from your links.toml, or from a plugin option, with\n# one exception: where `atlassian` or `slack` is left empty, an Agent Services\n# response that shows your Atlassian site or Slack workspace (a URL on\n# <name>.atlassian.net or <name>.slack.com) fills it. For Atlassian that is a\n# Jira answer's status or priority icon (iconUrl): the `self` URLs in Agent\n# Services' Jira answers go through api.atlassian.com, which names no site. Set one to a\n# site, or to \"\" in your own links.toml to turn it off, and nothing is learned\n# for it.\n# The atlassianBase, gleanBase and slackBase plugin options override these three.\n[bases]\natlassian = \"\"                # your Jira and Confluence site, e.g. https://yourco.atlassian.net; empty is learned from Agent Services' Jira answers (status and priority icons)\nglean = \"https://app.glean.com\"\nslack = \"\"                    # your Slack workspace, e.g. https://yourco.slack.com; empty is learned\nincidentio = \"https://app.incident.io\"\n# Hosts whose links a response carries itself (a permalink, a url, a webUrl):\n# naming the host here is what lets that link open. No rule needed.\ngoogledocs = \"https://docs.google.com\"\ngoogledrive = \"https://drive.google.com\"\ngong = \"https://app.gong.io\"\nhubspot = \"https://app.hubspot.com\"\nashby = \"https://app.ashbyhq.com\"\n\n# [[record]]: a result row's link. `service` is the root field's prefix before\n# `_` (`*` for any), `field` the item field holding the value (dotted ok:\n# fields.key), `match` an optional regex the value must fully satisfy, and\n# {value} in `url` the percent-encoded value. The first rule that matches wins.\n[[record]]\nservice = \"jira\"\nfield = \"key\"\nmatch = \"^[A-Z][A-Z0-9_]+-\\\\d+$\"\nurl = \"{atlassian}/browse/{value}\"\n\n[[record]]\nservice = \"jira\"\nfield = \"fields.key\"\nmatch = \"^[A-Z][A-Z0-9_]+-\\\\d+$\"\nurl = \"{atlassian}/browse/{value}\"\n\n[[record]]\nservice = \"confluence\"\nfield = \"id\"\nmatch = \"^\\\\d{1,20}$\"\nurl = \"{atlassian}/wiki/pages/viewpage.action?pageId={value}\"\n\n# A CQL search hit's page is under `content` (its own `url` is relative).\n[[record]]\nservice = \"confluence\"\nfield = \"content.id\"\nmatch = \"^\\\\d{1,20}$\"\nurl = \"{atlassian}/wiki/pages/viewpage.action?pageId={value}\"\n\n# [[search]]: a link for the whole operation, from one root's string argument.\n# `root` is a root field name, or a prefix when it ends in `*`.\n[[search]]\nlabel = \"Open in Confluence\"\nservice = \"confluence\"\nroot = \"confluence_*\"\narg = \"cql\"\nurl = \"{atlassian}/wiki/search?cql={value}\"\n\n[[search]]\nlabel = \"Open in Jira\"\nservice = \"jira\"\nroot = \"jira_*\"\narg = \"jql\"\nurl = \"{atlassian}/issues/?jql={value}\"\n\n[[search]]\nlabel = \"Open in Glean\"\nservice = \"glean\"\nroot = \"glean_search\"\narg = \"query\"\nurl = \"{glean}/search?q={value}\"\n\n# No Slack search link: its web search URL is unconfirmed, and a broken link is worse than none.\n# Messages link to themselves (their permalink, on the slack host above).\n"
